bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
new=create-videobot:video-dualmode-button-download-dc4578de
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
test "$(docker inspect "$cid" --format '{{.Image}}')" = "$(docker image inspect "$new" --format '{{.Id}}')" || exit 62
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 63
docker logs "$cid" 2>&1 | grep -Fq 'CREATOR_DM_POLL_READY=PASS' || exit 64
docker logs "$cid" 2>&1 | grep -Fq 'STICKER_SHOP_HTTP_READY=PASS' || exit 65
docker exec "$cid" grep -Fq "protect_content:false" /opt/videobot/src/telegram/videoInvoiceSales.mjs || exit 66
docker exec "$cid" grep -Fq "sendInvoice" /opt/videobot/src/telegram/videoInvoiceSales.mjs || exit 67
docker exec "$cid" grep -Fq "videoOfferLink" /opt/videobot/src/telegram/paidListingPublisher.mjs || exit 68
docker exec "$cid" grep -Fq "sendPaidMedia" /opt/videobot/src/telegram/paidListingPublisher.mjs || exit 69
docker exec "$cid" grep -Fq "invoice" /opt/videobot/src/sales/pgPostingReceipts.mjs || exit 70
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import pg from 'pg';
import {videoOfferLink} from './src/telegram/videoInvoiceSales.mjs';
assert.equal(videoOfferLink('CreateVdobot','listing1',1),
  'https://t.me/CreateVdobot?start=vid_listing1_r1');
const pass=readFileSync('/run/secrets/videobot_db_password','utf8').trim();
const pool=new pg.Pool({
  host:process.env.VIDEOBOT_DB_HOST,
  user:process.env.VIDEOBOT_DB_USER,
  database:process.env.VIDEOBOT_DB_NAME,
  password:pass,connectionTimeoutMillis:4500,max:1
});
try{
  const {rows}=await pool.query(`SELECT
    to_regclass('public.videobot_video_invoice_orders') IS NOT NULL AS invoice_table,
    EXISTS(SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name='videobot_post_receipts' AND column_name='sale_mode') AS sale_mode,
    to_regclass('public.videobot_stars_ledger') IS NOT NULL AS ledger`);
  assert.equal(rows.length,1);
  assert.deepEqual(rows[0],{invoice_table:true,sale_mode:true,ledger:true});
}finally{await pool.end();}
console.log('VIDEO_INVOICE_DATABASE_READBACK_PASS');
NODE
echo VIDEO_DUALMODE_INVOICE_DOWNLOAD_PRODUCTION_READBACK_PASS
